    keys.iter()
        .map(|key| {
            let key = key
                .as_str()
                .ok_or_else(|| invalid_value("`TagKeys` must hold strings".into()))?;
            check_key(key)?;
            Ok(key)
        })
        .collect()
}

impl Broker {
