    assert_eq!(h.err(json!({"Command": "TagQueue", "QueueName": 5})), "MissingParameter");
    assert_eq!(h.err(json!({"Command": "TagQueue", "Tags": null, "QueueName": "q"})), "MissingParameter");
    assert_eq!(
