pub(super) fn delete_from_queue(
    queue: &mut Queue,
    issued: u64,
    now: u64,
    handle: &str,
) -> Result<Members> {
    let key = in_flight_message(queue, issued, now, handle)?;
    queue.remove(key);
    Ok(Members::new())
}

