#[test]
fn entries_see_the_message_limit_effects_of_earlier_entries() {
    let mut h = Harness::new();
    create(&mut h, "q", json!({"RetentionSeconds": 1209600}));
    // Fill the queue to one below the limit with batches, then overflow within one.
    for _ in 0..9999 {
