#[test]
fn batch_rules_and_their_order() {
    let mut h = Harness::new();
    create(&mut h, "q", json!({}));
    let code = |h: &mut Harness, entries: Value| {
        h.err(json!({"Command": "SendMessageBatch", "QueueName": "q", "Entries": entries}))
    };
    assert_eq!(code(&mut h, json!([])), "EmptyBatchRequest");
    let eleven: Vec<Value> = (0..11).map(|i| json!({"Id": format!("{i}"), "Body": "x"})).collect();
    assert_eq!(code(&mut h, json!(eleven)), "TooManyEntriesInBatchRequest");
    // Rule 2 comes before rule 3, which comes before rule 4.
    let mut bad: Vec<Value> = (0..11).map(|_| json!({"Id": "same"})).collect();
    assert_eq!(code(&mut h, json!(bad.clone())), "TooManyEntriesInBatchRequest");
    bad.truncate(2);
    bad.push(json!(5));
    assert_eq!(code(&mut h, json!(bad)), "InvalidBatchEntryId");
    for entry in [
        json!("x"), json!(null), json!([]), json!({}), json!({"Id": null}), json!({"Id": 1}),
        json!({"Id": ""}), json!({"Id": "a b"}), json!({"Id": "é"}), json!({"Id": "x".repeat(81)}),
    ] {
        assert_eq!(code(&mut h, json!([{"Id": "ok", "Body": "x"}, entry])), "InvalidBatchEntryId");
    }
    assert_eq!(code(&mut h, json!([{"Id": "a", "Body": "x"}, {"Id": "a", "Body": "y"}])), "BatchEntryIdsNotDistinct");
    // Ids are case-sensitive; 80 characters is fine; 10 entries are fine.
    let ten: Vec<Value> = (0..10).map(|i| json!({"Id": format!("{i}"), "Body": "x"})).collect();
    assert_eq!(send_batch(&mut h, "q", json!(ten))["Successful"].as_array().unwrap().len(), 10);
    let r = send_batch(&mut h, "q", json!([{"Id": "a", "Body": "x"}, {"Id": "A", "Body": "x"}, {"Id": "x".repeat(80), "Body": "x"}]));
    assert_eq!(r["Successful"].as_array().unwrap().len(), 3);
    // A request failing a batch rule does nothing.
    assert_eq!(counts(&mut h, "q"), json!({"Visible": 13, "InFlight": 0, "Delayed": 0}));
}

#[test]
fn check_order_before_the_batch_rules() {
    let mut h = Harness::new();
    for cmd in ["SendMessageBatch", "DeleteMessageBatch"] {
